+            continue;
+        }
+        PrefixEvictionPlan::KeyPlan planned{
+            .key   = key,
+            .action = PrefixEvictionPlan::KeyPlan::Action::Evict};
+        for (const std::size_t index : group) {
+            const auto bytes =
+                record_evictable_bytes(records[index], device_page_bytes, state_image_bytes);
